# scripts/analyze_runtime_benchmarks.py
#
# Produces publication-ready runtime benchmarking figures and summary tables.
# Expects: benchmarking/runtime/runtime_benchmark_results.csv
#   (generated by scripts/parse_benchmark_results.py)
#
# Outputs:
#   benchmarking/runtime/runtime_summary_table.csv        – per-organism summary
#   benchmarking/runtime/Figure_Runtime_Scaling.png/pdf   – runtime + memory by size
#   benchmarking/runtime/Figure_Runtime_Efficiency.png    – time per sequence
#
import pandas as pd
import numpy as np
import matplotlib.pyplot as plt
import seaborn as sns
from sklearn.linear_model import LinearRegression
from sklearn.preprocessing import PolynomialFeatures

# ---------------------------------------------------------------------------
# Load and prepare data
# ---------------------------------------------------------------------------
plt.style.use('seaborn-v0_8-paper')
sns.set_palette("Set2")

df = pd.read_csv("benchmarking/runtime/runtime_benchmark_results.csv")
df = df[df['success'] == True].copy()

# Extract organism name from run_name  (e.g. "Carcharhiniformes_n1000_rep2")
df['organism'] = df['run_name'].str.extract(r'^(.+?)_n\d+_rep\d+$')

# Per-organism, per-size means (used for trend lines and summary table)
means = (
    df.groupby(['organism', 'n_sequences'])
    .agg(
        mean_time=('total_time', 'mean'),
        mean_memory_mb=('peak_memory_mb', 'mean'),
    )
    .reset_index()
)

# ---------------------------------------------------------------------------
# Per-organism polynomial fits  (degree 2, fitted on group means)
# ---------------------------------------------------------------------------
organisms = sorted(df['organism'].unique())
palette = dict(zip(organisms, sns.color_palette("Set2", n_colors=len(organisms))))
fits = {}                  # organism -> (poly_features, model, r2)
fit_curves = {}            # organism -> (x_smooth, y_smooth)

for org in organisms:
    grp = means[means['organism'] == org].sort_values('n_sequences')
    if len(grp) < 3:
        # Need ≥ 3 points for a degree-2 fit
        continue
    X = grp['n_sequences'].values.reshape(-1, 1)
    y = grp['mean_time'].values

    pf = PolynomialFeatures(degree=2)
    X_poly = pf.fit_transform(X)
    model = LinearRegression().fit(X_poly, y)
    r2 = model.score(X_poly, y)

    x_smooth = np.linspace(X.min(), X.max(), 100).reshape(-1, 1)
    y_smooth = model.predict(pf.transform(x_smooth))
    # Clip negative predictions (can happen at extrapolation edges)
    y_smooth = np.clip(y_smooth, 0, None)

    fits[org] = (pf, model, r2)
    fit_curves[org] = (x_smooth.ravel(), y_smooth)

print("Per-organism scaling fits (polynomial degree 2, on group means):")
for org, (_, _, r2) in fits.items():
    print(f"  {org}: R² = {r2:.3f}")

# ---------------------------------------------------------------------------
# Summary table
# ---------------------------------------------------------------------------
summary = (
    df.groupby(['organism', 'n_sequences'])
    .agg(
        n_runs=('total_time', 'count'),
        mean_time_sec=('total_time', 'mean'),
        std_time_sec=('total_time', 'std'),
        mean_memory_mb=('peak_memory_mb', 'mean'),
        max_memory_mb=('peak_memory_mb', 'max'),
        mean_cpu_pct=('avg_cpu_percent', 'mean'),
    )
    .round(1)
    .reset_index()
)
summary.to_csv("benchmarking/runtime/runtime_summary_table.csv", index=False)
print("\nRuntime Summary Table:")
print(summary.to_string(index=False))

# ---------------------------------------------------------------------------
# Figure 1: Runtime scaling + memory scaling (coloured by organism)
# ---------------------------------------------------------------------------
fig, axes = plt.subplots(1, 2, figsize=(12, 5))

# --- Panel A: Runtime ---
ax = axes[0]
sns.scatterplot(
    data=df, x='n_sequences', y='total_time',
    hue='organism', style='organism',
    alpha=0.5, s=60, ax=ax, legend='auto'
)
# Overlay per-organism polynomial trend on the group means
for org in organisms:
    if org not in fit_curves:
        continue
    x_s, y_s = fit_curves[org]
    ax.plot(x_s, y_s, color=palette[org], linewidth=2)

ax.set_xlabel('Number of Sequences', fontsize=12)
ax.set_ylabel('Total Runtime (seconds)', fontsize=12)
ax.set_title('A. Runtime Scaling', fontsize=14, fontweight='bold')
ax.legend(title='Organism', fontsize=8, title_fontsize=9)
ax.grid(True, alpha=0.3)

# --- Panel B: Memory ---
ax = axes[1]
sns.scatterplot(
    data=df, x='n_sequences', y='peak_memory_mb',
    hue='organism', style='organism',
    alpha=0.5, s=60, ax=ax, legend='auto'
)
# Connect group means per organism
for org in organisms:
    grp = means[means['organism'] == org].sort_values('n_sequences')
    ax.plot(grp['n_sequences'], grp['mean_memory_mb'],
            color=palette[org], linewidth=2)

ax.set_xlabel('Number of Sequences', fontsize=12)
ax.set_ylabel('Peak Memory (MB)', fontsize=12)
ax.set_title('B. Memory Scaling', fontsize=14, fontweight='bold')
ax.legend(title='Organism', fontsize=8, title_fontsize=9)
ax.grid(True, alpha=0.3)

plt.tight_layout()
plt.savefig('benchmarking/runtime/Figure_Runtime_Scaling.png', dpi=300, bbox_inches='tight')
plt.savefig('benchmarking/runtime/Figure_Runtime_Scaling.pdf', bbox_inches='tight')
print("\nSaved: Figure_Runtime_Scaling.png/pdf")

# ---------------------------------------------------------------------------
# Figure 2: Seconds per sequence at the largest tested dataset size per organism
#
# For each organism, take all replicates at its maximum tested N and plot
# mean ± std seconds/sequence as a bar chart.  Coloured by environment type.
# ---------------------------------------------------------------------------
env_colors = {
    'Carcharhiniformes': '#3182bd',  # marine
    'Panulirus':         '#3182bd',  # marine
    'Sphyrnidae':        '#3182bd',  # marine
    'Salmonidae':        '#31a354',  # freshwater
    'Pieridae':          '#a63603',  # terrestrial
}
env_labels = {
    'Carcharhiniformes': 'Marine',
    'Panulirus':         'Marine',
    'Sphyrnidae':        'Marine',
    'Salmonidae':        'Freshwater',
    'Pieridae':          'Terrestrial',
}

# For each organism get all replicates at the maximum tested N
efficiency_rows = []
for org in organisms:
    grp = df[df['organism'] == org]
    max_n = grp['n_sequences'].max()
    at_max = grp[grp['n_sequences'] == max_n].copy()
    at_max['time_per_seq'] = at_max['total_time'] / at_max['n_sequences']
    efficiency_rows.append({
        'organism':      org,
        'max_n':         max_n,
        'mean_tps':      at_max['time_per_seq'].mean(),
        'std_tps':       at_max['time_per_seq'].std(),
        'color':         env_colors.get(org, '#999999'),
        'env':           env_labels.get(org, 'Unknown'),
    })

eff_df = pd.DataFrame(efficiency_rows).sort_values('mean_tps', ascending=False)

fig, ax = plt.subplots(figsize=(8, 5))
x = np.arange(len(eff_df))
bars = ax.bar(
    x, eff_df['mean_tps'],
    yerr=eff_df['std_tps'],
    color=eff_df['color'],
    width=0.55,
    edgecolor='white', linewidth=0.8,
    capsize=5, error_kw=dict(elinewidth=1.2, capthick=1.2, ecolor='#333333'),
    zorder=3,
)

# Annotate each bar with the max N tested and mean value
for i, row in eff_df.reset_index(drop=True).iterrows():
    ax.text(i, row['mean_tps'] + row['std_tps'] + ax.get_ylim()[1] * 0.01,
            f"{row['mean_tps']:.2f}s",
            ha='center', va='bottom', fontsize=8.5, fontweight='bold', color='#222222')
    ax.text(i, -0.08, f"n={int(row['max_n']):,}",
            ha='center', va='top', fontsize=7.5, color='#666666',
            transform=ax.get_xaxis_transform())

ax.set_xticks(x)
ax.set_xticklabels(
    [f"{row['organism']}" for _, row in eff_df.iterrows()],
    fontsize=9
)
ax.set_ylabel('Seconds per Input Sequence\n(at largest tested dataset size)', fontsize=10)
ax.set_title('Runtime Efficiency by Dataset', fontsize=12, fontweight='bold')
ax.grid(axis='y', alpha=0.35, zorder=1)
ax.set_axisbelow(True)

# Environment legend
import matplotlib.patches as mpatches
legend_patches = [
    mpatches.Patch(facecolor='#3182bd', edgecolor='white', label='Marine'),
    mpatches.Patch(facecolor='#31a354', edgecolor='white', label='Freshwater'),
    mpatches.Patch(facecolor='#a63603', edgecolor='white', label='Terrestrial'),
]
ax.legend(handles=legend_patches, loc='upper right', fontsize=9, framealpha=0.9)
ax.text(0.99, 0.97, 'Error bars = std across replicates',
        ha='right', va='top', transform=ax.transAxes,
        fontsize=7.5, color='#666666', style='italic')

plt.tight_layout(rect=[0, 0.04, 1, 1])
plt.savefig('benchmarking/runtime/Figure_Runtime_Efficiency.png', dpi=300, bbox_inches='tight')
plt.savefig('benchmarking/runtime/Figure_Runtime_Efficiency.pdf', bbox_inches='tight')
print("Saved: Figure_Runtime_Efficiency.png/pdf")

# ---------------------------------------------------------------------------
# Print runtime estimates from each organism's model
# ---------------------------------------------------------------------------
print("\nEstimated runtimes (from per-organism polynomial fits):")
for org, (pf, model, r2) in sorted(fits.items()):
    grp = means[means['organism'] == org]
    max_tested = int(grp['n_sequences'].max())
    print(f"\n  {org} (R²={r2:.3f}, max tested n={max_tested}):")
    for n in [500, 1000, 2500, 5000, 10000]:
        if n > max_tested:
            break  # don't extrapolate
        pred = model.predict(pf.transform([[n]]))[0]
        print(f"    n={n:5d}: {pred/60:.1f} min ({pred:.0f} s)")